    "\u{1F90F}\u{1F3FF}": "\uAF2C\uC9D1\uB294 \uC190: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAF2C\uC9D1\uB294 \uC190 \uC190\uAC00\uB77D \uC801\uC740 \uC591\uC744 \uB098\uD0C0\uB0B4\uB294 \uC190 \uC870\uAE08 \uD55C \uAF2C\uC9D1",
    "\u270C\uFE0F": "\uBE0C\uC774 \uD45C\uC2DC \uAC00\uC704 \uBE0C\uC774\uD558\uB294 \uC190 \uBE45\uD1A0\uB9AC \uC190 \uC2B9\uB9AC \uCC0C \uD3C9\uD654",
    "\u270C\u{1F3FB}": "\uBE0C\uC774 \uD45C\uC2DC: \uD558\uC580 \uD53C\uBD80 \uAC00\uC704 \uBE0C\uC774 \uD45C\uC2DC \uBE0C\uC774\uD558\uB294 \uC190 \uBE45\uD1A0\uB9AC \uC190 \uC2B9\uB9AC \uCC0C \uD3C9\uD654 \uD558\uC580 \uD53C\uBD80",
    "\u270C\u{1F3FC}": "\uBE0C\uC774 \uD45C\uC2DC: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uAC00\uC704 \uBE0C\uC774 \uD45C\uC2DC \uBE0C\uC774\uD558\uB294 \uC190 \uBE45\uD1A0\uB9AC \uC190 \uC2B9\uB9AC \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uCC0C \uD3C9\uD654",
    "\u270C\u{1F3FD}": "\uBE0C\uC774 \uD45C\uC2DC: \uAC08\uC0C9 \uD53C\uBD80 \uAC00\uC704 \uAC08\uC0C9 \uD53C\uBD80 \uBE0C\uC774 \uD45C\uC2DC \uBE0C\uC774\uD558\uB294 \uC190 \uBE45\uD1A0\uB9AC \uC190 \uC2B9\uB9AC \uCC0C \uD3C9\uD654",
