    "\u{1F9CF}\u200D\u2642\uFE0F": "\uCCAD\uAC01\uC7A5\uC560\uAC00 \uC788\uB294 \uB0A8\uC790 \uB0A8\uC790 \uCCAD\uAC01\uC7A5\uC560",
    "\u{1F9CF}\u{1F3FB}\u200D\u2642\uFE0F": "\uCCAD\uAC01\uC7A5\uC560\uAC00 \uC788\uB294 \uB0A8\uC790: \uD558\uC580 \uD53C\uBD80 \uB0A8\uC790 \uCCAD\uAC01\uC7A5\uC560 \uCCAD\uAC01\uC7A5\uC560\uAC00 \uC788\uB294 \uB0A8\uC790 \uD558\uC580 \uD53C\uBD80",
    "\u{1F9CF}\u{1F3FC}\u200D\u2642\uFE0F": "\uCCAD\uAC01\uC7A5\uC560\uAC00 \uC788\uB294 \uB0A8\uC790: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB0A8\uC790 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uCCAD\uAC01\uC7A5\uC560 \uCCAD\uAC01\uC7A5\uC560\uAC00 \uC788\uB294 \uB0A8\uC790",
