    "\u{1F9CF}\u200D\u2640\uFE0F": "\uCCAD\uAC01\uC7A5\uC560\uAC00 \uC788\uB294 \uC5EC\uC790 \uC5EC\uC790 \uCCAD\uAC01\uC7A5\uC560",
