    "\u{1F9DD}\u{1F3FB}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC5D8\uD504: \uD558\uC580 \uD53C\uBD80 \uB9C8\uBC95 \uC2E0\uD654 \uC5D8\uD504 \uC5EC\uC790 \uC5D8\uD504 \uC694\uC815 \uC804\uC124 \uD310\uD0C0\uC9C0 \uD558\uC580 \uD53C\uBD80",
    "\u{1F9DD}\u{1F3FC}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC5D8\uD504: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB9C8\uBC95 \uC2E0\uD654 \uC5D8\uD504 \uC5EC\uC790 \uC5D8\uD504 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC694\uC815 \uC804\uC124 \uD310\uD0C0\uC9C0",
    "\u{1F9DD}\u{1F3FD}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC5D8\uD504: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uB9C8\uBC95 \uC2E0\uD654 \uC5D8\uD504 \uC5EC\uC790 \uC5D8\uD504 \uC694\uC815 \uC804\uC124 \uD310\uD0C0\uC9C0",
    "\u{1F9DD}\u{1F3FE}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC5D8\uD504: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB9C8\uBC95 \uC2E0\uD654 \uC5D8\uD504 \uC5EC\uC790 \uC5D8\uD504 \uC694\uC815 \uC804\uC124 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uD310\uD0C0\uC9C0",
    "\u{1F9DD}\u{1F3FF}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC5D8\uD504: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uB9C8\uBC95 \uC2E0\uD654 \uC5D8\uD504 \uC5EC\uC790 \uC5D8\uD504 \uC694\uC815 \uC804\uC124 \uD310\uD0C0\uC9C0",
    "\u{1F9DE}": "\uC9C0\uB2C8 \uB7A8\uD504 \uBB38\uC9C0\uB974\uAE30 \uC18C\uC6D0 \uC815\uB839 \uD310\uD0C0\uC9C0",
    "\u{1F9DE}\u200D\u2642\uFE0F": "\uB0A8\uC790 \uC9C0\uB2C8 \uB7A8\uD504 \uBB38\uC9C0\uB974\uAE30 \uC18C\uC6D0 \uC815\uB839 \uC9C0\uB2C8 \uD310\uD0C0\uC9C0",
    "\u{1F9DE}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC9C0\uB2C8 \uB7A8\uD504 \uBB38\uC9C0\uB974\uAE30 \uC18C\uC6D0 \uC815\uB839 \uC9C0\uB2C8 \uD310\uD0C0\uC9C0",
    "\u{1F9DF}": "\uC880\uBE44 \uACF5\uD3EC \uC544\uD3EC\uCE7C\uB9BD\uC2A4 \uC5B8\uB370\uB4DC \uC6CC\uD0B9 \uB370\uB4DC \uD560\uB85C\uC708 \uD638\uB7EC",
    "\u{1F9DF}\u200D\u2642\uFE0F": "\uB0A8\uC790 \uC880\uBE44 \uACF5\uD3EC \uC544\uD3EC\uCE7C\uB9BD\uC2A4 \uC5B8\uB370\uB4DC \uC6CC\uD0B9 \uB370\uB4DC \uC880\uBE44 \uD560\uB85C\uC708 \uD638\uB7EC",
    "\u{1F9DF}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC880\uBE44 \uACF5\uD3EC \uC544\uD3EC\uCE7C\uB9BD\uC2A4 \uC5B8\uB370\uB4DC \uC6CC\uD0B9 \uB370\uB4DC \uC880\uBE44 \uD560\uB85C\uC708 \uD638\uB7EC",
    "\u{1F9CC}": "\uD2B8\uB864 \uAD34\uBB3C \uB3D9\uD654 \uBAAC\uC2A4\uD130 \uD2B8\uB864\uB9C1 \uD310\uD0C0\uC9C0",
    "\u{1FAC8}": "\uD138\uBCF5\uC22D\uC774 \uAC70\uC778 \uAD34\uC0DD\uBA85\uCCB4 \uBE45\uD48B \uC0AC\uC2A4\uCF70\uCE58 \uC124\uC778 \uC232 \uD138",
    "\u{1F486}": "\uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C \uACBD\uB77D \uACE8\uCE58\uC544\uD514 \uAE34\uC7A5 \uB450\uD1B5 \uB9C8\uC0AC\uC9C0 \uB9C8\uC0AC\uC9C0\uB97C \uBC1B\uB294 \uC0AC\uB78C \uB9E4\uB048 \uC0B4\uB871 \uC2A4\uD30C \uC5BC\uAD74 \uC694\uBC95 \uC774\uC644 \uCE58\uB8CC \uD14C\uB77C\uD53C \uD2B8\uB9AC\uD2B8\uBA3C\uD2B8",
    "\u{1F486}\u{1F3FB}": "\uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C: \uD558\uC580 \uD53C\uBD80 \uACBD\uB77D \uACE8\uCE58\uC544\uD514 \uAE34\uC7A5 \uB450\uD1B5 \uB9C8\uC0AC\uC9C0 \uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C \uB9C8\uC0AC\uC9C0\uB97C \uBC1B\uB294 \uC0AC\uB78C \uB9E4\uB048 \uC0B4\uB871 \uC2A4\uD30C \uC5BC\uAD74 \uC694\uBC95 \uC774\uC644 \uCE58\uB8CC \uD14C\uB77C\uD53C \uD2B8\uB9AC\uD2B8\uBA3C\uD2B8 \uD558\uC580 \uD53C\uBD80",
    "\u{1F486}\u{1F3FC}": "\uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uACBD\uB77D \uACE8\uCE58\uC544\uD514 \uAE34\uC7A5 \uB450\uD1B5 \uB9C8\uC0AC\uC9C0 \uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C \uB9C8\uC0AC\uC9C0\uB97C \uBC1B\uB294 \uC0AC\uB78C \uB9E4\uB048 \uC0B4\uB871 \uC2A4\uD30C \uC5BC\uAD74 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC694\uBC95 \uC774\uC644 \uCE58\uB8CC \uD14C\uB77C\uD53C \uD2B8\uB9AC\uD2B8\uBA3C\uD2B8",
    "\u{1F486}\u{1F3FD}": "\uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uACBD\uB77D \uACE8\uCE58\uC544\uD514 \uAE34\uC7A5 \uB450\uD1B5 \uB9C8\uC0AC\uC9C0 \uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C \uB9C8\uC0AC\uC9C0\uB97C \uBC1B\uB294 \uC0AC\uB78C \uB9E4\uB048 \uC0B4\uB871 \uC2A4\uD30C \uC5BC\uAD74 \uC694\uBC95 \uC774\uC644 \uCE58\uB8CC \uD14C\uB77C\uD53C \uD2B8\uB9AC\uD2B8\uBA3C\uD2B8",
    "\u{1F486}\u{1F3FE}": "\uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uACBD\uB77D \uACE8\uCE58\uC544\uD514 \uAE34\uC7A5 \uB450\uD1B5 \uB9C8\uC0AC\uC9C0 \uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C \uB9C8\uC0AC\uC9C0\uB97C \uBC1B\uB294 \uC0AC\uB78C \uB9E4\uB048 \uC0B4\uB871 \uC2A4\uD30C \uC5BC\uAD74 \uC694\uBC95 \uC774\uC644 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uCE58\uB8CC \uD14C\uB77C\uD53C \uD2B8\uB9AC\uD2B8\uBA3C\uD2B8",
