    "\u{1F9D7}\u{1F3FF}\u200D\u2640\uFE0F": "\uD074\uB77C\uC774\uBC0D\uD558\uB294 \uC5EC\uC790: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uB4F1\uBC18 \uB4F1\uC0B0 \uB4F1\uC0B0\uAC00 \uC0B0 \uC554\uBCBD \uB4F1\uBC18 \uC554\uBCBD \uB4F1\uBC18\uAC00 \uD074\uB77C\uC774\uBC0D \uD074\uB77C\uC774\uBC0D\uD558\uB294 \uC5EC\uC790",
    "\u{1F93A}": "\uD39C\uC2F1\uD558\uB294 \uC0AC\uB78C \uAC80 \uC120\uC218 \uC2A4\uD3EC\uCE20 \uCE7C \uD39C\uC2F1",
    "\u{1F3C7}": "\uC2B9\uB9C8 \uACBD\uB9C8 \uAE30\uC218 \uB808\uC774\uC2F1 \uB9D0 \uB9D0\uACFC \uAE30\uC218 \uC2A4\uD3EC\uCE20 \uD2B8\uB9AC\uD50C \uD06C\uB77C\uC6B4",
    "\u{1F3C7}\u{1F3FB}": "\uC2B9\uB9C8: \uD558\uC580 \uD53C\uBD80 \uACBD\uB9C8 \uAE30\uC218 \uB808\uC774\uC2F1 \uB9D0 \uB9D0\uACFC \uAE30\uC218 \uC2A4\uD3EC\uCE20 \uC2B9\uB9C8 \uD2B8\uB9AC\uD50C \uD06C\uB77C\uC6B4 \uD558\uC580 \uD53C\uBD80",
    "\u{1F3C7}\u{1F3FC}": "\uC2B9\uB9C8: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uACBD\uB9C8 \uAE30\uC218 \uB808\uC774\uC2F1 \uB9D0 \uB9D0\uACFC \uAE30\uC218 \uC2A4\uD3EC\uCE20 \uC2B9\uB9C8 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uD2B8\uB9AC\uD50C \uD06C\uB77C\uC6B4",
    "\u{1F3C7}\u{1F3FD}": "\uC2B9\uB9C8: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uACBD\uB9C8 \uAE30\uC218 \uB808\uC774\uC2F1 \uB9D0 \uB9D0\uACFC \uAE30\uC218 \uC2A4\uD3EC\uCE20 \uC2B9\uB9C8 \uD2B8\uB9AC\uD50C \uD06C\uB77C\uC6B4",
    "\u{1F3C7}\u{1F3FE}": "\uC2B9\uB9C8: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uACBD\uB9C8 \uAE30\uC218 \uB808\uC774\uC2F1 \uB9D0 \uB9D0\uACFC \uAE30\uC218 \uC2A4\uD3EC\uCE20 \uC2B9\uB9C8 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uD2B8\uB9AC\uD50C \uD06C\uB77C\uC6B4",
    "\u{1F3C7}\u{1F3FF}": "\uC2B9\uB9C8: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uACBD\uB9C8 \uAE30\uC218 \uB808\uC774\uC2F1 \uB9D0 \uB9D0\uACFC \uAE30\uC218 \uC2A4\uD3EC\uCE20 \uC2B9\uB9C8 \uD2B8\uB9AC\uD50C \uD06C\uB77C\uC6B4",
    "\u26F7\uFE0F": "\uC2A4\uD0A4 \uD0C0\uB294 \uC0AC\uB78C \uB208 \uC2A4\uD0A4 \uC2A4\uD0A4\uD0C0\uB294 \uC0AC\uB78C",
    "\u{1F3C2}": "\uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C \uB208 \uC2A4\uB178\uBCF4\uB354 \uC2A4\uB178\uBCF4\uB4DC \uC2A4\uD0A4 \uC2A4\uD3EC\uCE20 \uC6B4\uB3D9",
    "\u{1F3C2}\u{1F3FB}": "\uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C: \uD558\uC580 \uD53C\uBD80 \uB208 \uC2A4\uB178\uBCF4\uB354 \uC2A4\uB178\uBCF4\uB4DC \uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C \uC2A4\uD0A4 \uC2A4\uD3EC\uCE20 \uC6B4\uB3D9 \uD558\uC580 \uD53C\uBD80",
    "\u{1F3C2}\u{1F3FC}": "\uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB208 \uC2A4\uB178\uBCF4\uB354 \uC2A4\uB178\uBCF4\uB4DC \uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C \uC2A4\uD0A4 \uC2A4\uD3EC\uCE20 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC6B4\uB3D9",
    "\u{1F3C2}\u{1F3FD}": "\uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uB208 \uC2A4\uB178\uBCF4\uB354 \uC2A4\uB178\uBCF4\uB4DC \uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C \uC2A4\uD0A4 \uC2A4\uD3EC\uCE20 \uC6B4\uB3D9",
    "\u{1F3C2}\u{1F3FE}": "\uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB208 \uC2A4\uB178\uBCF4\uB354 \uC2A4\uB178\uBCF4\uB4DC \uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C \uC2A4\uD0A4 \uC2A4\uD3EC\uCE20 \uC6B4\uB3D9 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80",
    "\u{1F3C2}\u{1F3FF}": "\uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uB208 \uC2A4\uB178\uBCF4\uB354 \uC2A4\uB178\uBCF4\uB4DC \uC2A4\uB178\uBCF4\uB4DC \uD0C0\uB294 \uC0AC\uB78C \uC2A4\uD0A4 \uC2A4\uD3EC\uCE20 \uC6B4\uB3D9",
    "\u{1F3CC}\uFE0F": "\uACE8\uD504\uCE58\uB294 \uC0AC\uB78C \uACE8\uD37C \uACE8\uD504 \uACE8\uD504 \uC120\uC218 \uACE8\uD504 \uC5F0\uC2B5\uC7A5 \uACE8\uD504\uD2F0 \uACF5 \uADF8\uB9B0 \uBC84\uB514 \uCE90\uB514 \uD37C\uD2B8 \uD544\uB4DC",
    "\u{1F3CC}\u{1F3FB}": "\uACE8\uD504\uCE58\uB294 \uC0AC\uB78C: \uD558\uC580 \uD53C\uBD80 \uACE8\uD37C \uACE8\uD504 \uACE8\uD504 \uC120\uC218 \uACE8\uD504 \uC5F0\uC2B5\uC7A5 \uACE8\uD504\uCE58\uB294 \uC0AC\uB78C \uACE8\uD504\uD2F0 \uACF5 \uADF8\uB9B0 \uBC84\uB514 \uCE90\uB514 \uD37C\uD2B8 \uD544\uB4DC \uD558\uC580 \uD53C\uBD80",
    "\u{1F3CC}\u{1F3FC}": "\uACE8\uD504\uCE58\uB294 \uC0AC\uB78C: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uACE8\uD37C \uACE8\uD504 \uACE8\uD504 \uC120\uC218 \uACE8\uD504 \uC5F0\uC2B5\uC7A5 \uACE8\uD504\uCE58\uB294 \uC0AC\uB78C \uACE8\uD504\uD2F0 \uACF5 \uADF8\uB9B0 \uBC84\uB514 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uCE90\uB514 \uD37C\uD2B8 \uD544\uB4DC",
    "\u{1F3CC}\u{1F3FD}": "\uACE8\uD504\uCE58\uB294 \uC0AC\uB78C: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uACE8\uD37C \uACE8\uD504 \uACE8\uD504 \uC120\uC218 \uACE8\uD504 \uC5F0\uC2B5\uC7A5 \uACE8\uD504\uCE58\uB294 \uC0AC\uB78C \uACE8\uD504\uD2F0 \uACF5 \uADF8\uB9B0 \uBC84\uB514 \uCE90\uB514 \uD37C\uD2B8 \uD544\uB4DC",
    "\u{1F3CC}\u{1F3FE}": "\uACE8\uD504\uCE58\uB294 \uC0AC\uB78C: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uACE8\uD37C \uACE8\uD504 \uACE8\uD504 \uC120\uC218 \uACE8\uD504 \uC5F0\uC2B5\uC7A5 \uACE8\uD504\uCE58\uB294 \uC0AC\uB78C \uACE8\uD504\uD2F0 \uACF5 \uADF8\uB9B0 \uBC84\uB514 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uCE90\uB514 \uD37C\uD2B8 \uD544\uB4DC",
    "\u{1F3CC}\u{1F3FF}": "\uACE8\uD504\uCE58\uB294 \uC0AC\uB78C: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uACE8\uD37C \uACE8\uD504 \uACE8\uD504 \uC120\uC218 \uACE8\uD504 \uC5F0\uC2B5\uC7A5 \uACE8\uD504\uCE58\uB294 \uC0AC\uB78C \uACE8\uD504\uD2F0 \uACF5 \uADF8\uB9B0 \uBC84\uB514 \uCE90\uB514 \uD37C\uD2B8 \uD544\uB4DC",
    "\u{1F3CC}\uFE0F\u200D\u2642\uFE0F": "\uACE8\uD504\uCE58\uB294 \uB0A8\uC790 \uACE8\uD37C \uACE8\uD504 \uACE8\uD504 \uC120\uC218 \uACE8\uD504 \uC5F0\uC2B5\uC7A5 \uACE8\uD504\uD2F0 \uACF5 \uADF8\uB9B0 \uBC84\uB514 \uC2A4\uC719 \uCE90\uB514 \uD37C\uD2B8",
