    "\u{1F5E3}\uFE0F": "\uB9D0\uD558\uACE0 \uC788\uB294 \uC606\uC5BC\uAD74 \uB9D0\uD558\uB294 \uB9D0\uD568 \uBA38\uB9AC \uC2E4\uB8E8\uC5E3 \uC5BC\uAD74",
    "\u{1F464}": "\uC0AC\uB78C \uADF8\uB9BC\uC790 \uBBF8\uC2A4\uD14C\uB9AC\uD55C \uC0AC\uB78C \uC0C1\uBC18\uC2E0 \uC0C1\uCCB4 \uC2E4\uB8E8\uC5E3",
    "\u{1F465}": "\uC0AC\uB78C\uB4E4 \uADF8\uB9BC\uC790 \uC0AC\uB78C\uB4E4 \uC0C1\uBC18\uC2E0 \uC0C1\uCCB4 \uC0C1\uCCB4 \uADF8\uB9BC\uC790 \uC601\uC6D0\uD55C \uBCA0\uC2A4\uD2B8\uD504\uB80C\uB4DC \uCE5C\uAD6C\uB4E4",
    "\u{1FAC2}": "\uD3EC\uC639\uD558\uB294 \uC0AC\uB78C \uACE0\uB9C8\uC6CC \uAD7F\uBC14\uC774 \uC0AC\uB791 \uC548\uB155 \uC548\uC544\uC8FC\uAE30 \uC6B0\uC815 \uC774\uBCC4 \uC798 \uAC00 \uD3B8\uC548\uD55C \uD3EC\uC639 \uD5C8\uADF8",
