    "\u{1FAC6}": "\uC9C0\uBB38 \uB2E8\uC11C \uBBF8\uC2A4\uD130\uB9AC \uBC94\uC8C4 \uC2E0\uC6D0 \uC548\uC804 \uCD94\uC801 \uD0D0\uC815 \uD3EC\uB80C\uC2DD \uD504\uB9B0\uD2B8",
    "\u{1F435}": "\uC6D0\uC22D\uC774 \uC5BC\uAD74 \uB3D9\uBB3C \uBC14\uB098\uB098 \uC5BC\uAD74 \uC6D0\uC22D\uC774 \uC6D0\uC22D\uC774\uB760",
    "\u{1F412}": "\uC6D0\uC22D\uC774 \uB3D9\uBB3C",
    "\u{1F98D}": "\uACE0\uB9B4\uB77C \uB3D9\uBB3C",
    "\u{1F9A7}": "\uC624\uB791\uC6B0\uD0C4 \uB3D9\uBB3C \uC6D0\uC22D\uC774 \uC720\uC778\uC6D0",
