    "\u{1F9AE}": "\uC548\uB0B4\uACAC \uC2DC\uAC01\uC7A5\uC560 \uC548\uB0B4 \uC811\uADFC\uC131",
    "\u{1F415}\u200D\u{1F9BA}": "\uBCF4\uC870\uACAC \uAC1C \uBCF4\uC870 \uC11C\uBE44\uC2A4 \uC811\uADFC\uC131",
    "\u{1F429}": "\uD478\uB4E4 \uAC15\uC544\uC9C0 \uAC1C \uB3D9\uBB3C \uBA4D\uBA4D\uC774 \uBCF5\uC2E4\uBCF5\uC2E4\uD55C",
    "\u{1F43A}": "\uB291\uB300 \uC5BC\uAD74 \uB291\uB300 \uB3D9\uBB3C \uC5BC\uAD74",
    "\u{1F98A}": "\uC5EC\uC6B0 \uC5BC\uAD74 \uB3D9\uBB3C \uC5BC\uAD74 \uC5EC\uC6B0",
    "\u{1F99D}": "\uB108\uAD6C\uB9AC \uB3D9\uBB3C \uB77C\uCFE4 \uC7A5\uB09C\uAE30 \uC788\uB294 \uD638\uAE30\uC2EC",
    "\u{1F431}": "\uACE0\uC591\uC774 \uC5BC\uAD74 \uACE0\uC591\uC774 \uB3D9\uBB3C \uC0C8\uB07C \uACE0\uC591\uC774 \uC560\uC644\uB3D9\uBB3C \uC5BC\uAD74 \uD0A4\uD2F0",
    "\u{1F408}": "\uACE0\uC591\uC774 \uAD2D\uC774 \uB0D0\uC639\uC774 \uB3D9\uBB3C \uC0C8\uB07C \uACE0\uC591\uC774 \uC560\uC644\uB3D9\uBB3C \uC57C\uC639\uC774 \uC9D1\uC0AC",
    "\u{1F408}\u200D\u2B1B": "\uAC80\uC740 \uACE0\uC591\uC774 \uAC80\uC740 \uACE0\uC591\uC774 \uACE0\uC591\uC774 \uAC19\uC740 \uB3D9\uBB3C \uBD88\uAE38\uD55C \uBD88\uD589 \uC57C\uC639 \uD560\uB85C\uC708 \uD57C\uB7EC\uC708",
    "\u{1F981}": "\uC0AC\uC790 \uC5BC\uAD74 \uAC08\uAE30 \uB3D9\uBB3C \uB808\uC624 \uC0AC\uC790 \uC0AC\uC790\uC790\uB9AC \uC0AC\uD30C\uB9AC \uC54C\uD30C \uC5BC\uAD74 \uC73C\uB974\uB801\uAC70\uB9AC\uB294 \uD798\uC774 \uC13C",
    "\u{1F42F}": "\uD638\uB791\uC774 \uC5BC\uAD74 \uB3D9\uBB3C \uC5BC\uAD74 \uD3EC\uC2DD\uC790 \uD638\uB791\uC774 \uD638\uB791\uC774\uB760",
    "\u{1F405}": "\uD638\uB791\uC774 \uB3D9\uBB3C \uB3D9\uBB3C\uC6D0 \uD070 \uACE0\uC591\uC774\uACFC \uB3D9\uBB3C \uD0C0\uC774\uAC70 \uD3EC\uC2DD\uC790",
    "\u{1F406}": "\uD45C\uBC94 \uB3D9\uBB3C \uB3D9\uBB3C\uC6D0 \uB808\uC624\uD30C\uB4DC \uD070 \uACE0\uC591\uC774\uACFC \uB3D9\uBB3C \uD3EC\uC2DD\uC790",
    "\u{1F434}": "\uB9D0 \uC5BC\uAD74 \uB18D\uC7A5 \uB3D9\uBB3C \uB9C8\uC7A5\uB9C8\uC220 \uB9D0 \uB9D0\uB760 \uC5BC\uAD74",
    "\u{1FACE}": "\uBB34\uC2A4 \uAC00\uC9C0\uC9C4 \uBFD4 \uB3D9\uBB3C \uC5D8\uD06C \uD3EC\uC720\uB3D9\uBB3C",
    "\u{1FACF}": "\uB2F9\uB098\uADC0 \uACE0\uC9D1\uBD88\uD1B5 \uB178\uC0C8 \uB3D9\uBB3C \uC5C9\uB369\uC774 \uD3EC\uC720\uB3D9\uBB3C",
    "\u{1F40E}": "\uB9D0 \uACBD\uB9C8 \uB3D9\uBB3C \uB808\uC774\uC2A4 \uB808\uC774\uC2F1 \uBCA8\uBAAC\uD2B8 \uC2A4\uD14C\uC774\uD06C \uC2B9\uB9C8 \uCF04\uD130\uD0A4 \uB354\uBE44 \uD2B8\uB9AC\uD50C \uD06C\uB77C\uC6B4",
    "\u{1F984}": "\uC720\uB2C8\uCF58 \uC5BC\uAD74 \uC5BC\uAD74 \uC720\uB2C8\uCF58",
    "\u{1F993}": "\uC5BC\uB8E9\uB9D0 \uC904\uBB34\uB2AC",
    "\u{1F98C}": "\uC0AC\uC2B4 \uB3D9\uBB3C",
    "\u{1F9AC}": "\uB4E4\uC18C \uB3D9\uBB3C \uB5BC \uBB3C\uC18C \uBC14\uC774\uC2A8",
