    "\u{1F402}": "\uC18C \uB18D\uC7A5 \uB3D9\uBB3C \uBCC4\uC790\uB9AC \uD669\uC18C \uD669\uC18C\uC790\uB9AC",
    "\u{1F403}": "\uBB3C\uC18C \uB3D9\uBB3C \uB3D9\uBB3C\uC6D0 \uBC84\uD314\uB85C \uC18C",
    "\u{1F404}": "\uC816\uC18C \uB18D\uC7A5 \uB3D9\uBB3C \uC18C \uC6B0\uC720 \uC74C\uBA54",
    "\u{1F437}": "\uB3FC\uC9C0 \uC5BC\uAD74 \uB18D\uC7A5 \uB3D9\uBB3C \uB3FC\uC9C0 \uB3FC\uC9C0\uACE0\uAE30 \uB3FC\uC9C0\uB760 \uBCA0\uC774\uCEE8 \uC70C\uBC84",
    "\u{1F416}": "\uB3FC\uC9C0 \uAFC0\uAFC0\uC774 \uB18D\uC7A5 \uB3D9\uBB3C \uB3FC\uC9C0\uACE0\uAE30 \uBCA0\uC774\uCEE8 \uC554\uD1D8\uC9C0",
    "\u{1F417}": "\uBA67\uB3FC\uC9C0 \uB3D9\uBB3C \uB3FC\uC9C0 \uD53C\uADF8",
    "\u{1F43D}": "\uB3FC\uC9C0\uCF54 \uAFC0\uAFC0 \uB18D\uC7A5 \uB3D9\uBB3C \uC5BC\uAD74 \uC8FC\uB465\uC774 \uCF54",
    "\u{1F40F}": "\uC22B\uC591 \uB3D9\uBB3C \uB3D9\uBB3C\uC6D0 \uBCC4\uC790\uB9AC \uC591\uC790\uB9AC",
    "\u{1F411}": "\uC591 \uB18D\uC7A5 \uB3D9\uBB3C \uB9E4~ \uBCF5\uC2E4\uBCF5\uC2E4\uD55C \uC0C8\uB07C \uC591 \uC554\uC591 \uC6B8",
    "\u{1F410}": "\uC5FC\uC18C \uB18D\uC7A5 \uB3D9\uBB3C \uBCC4\uC790\uB9AC \uC5FC\uC18C\uC790\uB9AC \uC6B0\uC720",
    "\u{1F42A}": "\uB099\uD0C0 \uB2E8\uBD09 \uB099\uD0C0 \uB3D9\uBB3C \uC0AC\uB9C9 \uD639",
    "\u{1F42B}": "\uC30D\uBD09 \uB099\uD0C0 \uB099\uD0C0 \uB3D9\uBB3C \uC30D\uBD09 \uD639",
    "\u{1F999}": "\uB77C\uB9C8 \uACFC\uB098\uCF54 \uB3D9\uBB3C \uBE44\uD050\uB098 \uC54C\uD30C\uCE74 \uC6B8",
    "\u{1F992}": "\uAE30\uB9B0 \uB3D9\uBB3C \uC5BC\uB8E9 \uC810",
    "\u{1F418}": "\uCF54\uB07C\uB9AC \uB3D9\uBB3C",
