    "\u{1F566}": "\uC5F4\uD55C \uC2DC \uBC18 11:30 11\uC2DC 30\uBD84 \uC2DC\uAC04 \uC2DC\uACC4",
    "\u{1F311}": "\uC0AD \uADF8\uBBD0 \uADF8\uBBD0\uB2EC \uB274\uBB38 \uB2EC \uC6B0\uC8FC \uCD08\uC2B9\uB2EC",
    "\u{1F312}": "\uCD08\uC2B9\uB2EC \uC0C1\uD604 \uAFC8 \uB2EC \uC0C1\uD604 \uC0C1\uD604\uB2EC \uC6B0\uC8FC",
    "\u{1F313}": "\uC624\uB978\uCABD \uBC18\uB2EC \uB2EC \uBC18\uB2EC \uC0C1\uD604 \uBC18\uB2EC \uC6B0\uC8FC",
    "\u{1F314}": "\uC0C1\uD604\uB2EC \uB2EC \uC6B0\uC8FC \uCCA0\uC6D4",
    "\u{1F315}": "\uBCF4\uB984\uB2EC \uB2EC \uB9CC\uC6D4 \uC6B0\uC8FC",
