    "\u{1F317}": "\uC67C\uCABD \uBC18\uB2EC \uB2EC \uBC18\uB2EC \uC6B0\uC8FC \uD558\uD604 \uBC18\uB2EC",
    "\u{1F318}": "\uADF8\uBBD0\uB2EC \uD558\uD604 \uADF8\uBBD0\uB2EC \uB2EC \uC6B0\uC8FC \uC810\uC810 \uC791\uC544\uC9C0\uB294 \uCD08\uC2B9\uB2EC",
    "\u{1F319}": "\uCD08\uC2B9\uB2EC \uB2EC \uB77C\uB9C8\uB2E8 \uC6B0\uC8FC",
    "\u{1F31A}": "\uC5BC\uAD74\uC774 \uC788\uB294 \uC0AD \uB274\uBB38 \uB2EC \uB2EC\uB2D8 \uB2EC\uC704\uC5D0 \uC5BC\uAD74 \uC0AD \uC5BC\uAD74 \uC6B0\uC8FC",
    "\u{1F31B}": "\uC5BC\uAD74\uC774 \uC788\uB294 \uCD08\uC2B9\uB2EC \uB2EC \uB2EC\uB2D8 \uC5BC\uAD74 \uC6B0\uC8FC",
    "\u{1F31C}": "\uADF8\uBBD0\uB2EC \uAFC8 \uB2EC \uB2EC\uB2D8 \uBC18\uB2EC \uC5BC\uAD74 \uC5BC\uAD74\uC774 \uC788\uB294 \uADF8\uBBD0\uB2EC \uC5BC\uAD74\uC774 \uC788\uB294 \uC0C1\uD604 \uBC18\uB2EC",
    "\u{1F321}\uFE0F": "\uC628\uB3C4\uACC4 \uB0A0\uC528 \uC628\uB3C4",
    "\u2600\uFE0F": "\uD0DC\uC591 \uB0A0\uC528 \uB354\uC6C0 \uB9D1\uC74C \uD574 \uD654\uCC3D\uD55C",
    "\u{1F31D}": "\uC5BC\uAD74\uC774 \uC788\uB294 \uBCF4\uB984\uB2EC \uB2EC \uB2EC\uB2D8 \uBC1D\uC74C \uC5BC\uAD74",
    "\u{1F31E}": "\uC5BC\uAD74\uC774 \uC788\uB294 \uD574 \uB0A0\uC528 \uB0AE \uB208\uBD80\uC2E0 \uBC1D\uC740 \uC5BC\uAD74 \uC5F4\uAE30 \uD574 \uBC29\uAE0B \uD574\uB2D8 \uD587\uBE5B",
    "\u{1FA90}": "\uACE0\uB9AC\uAC00 \uC788\uB294 \uD589\uC131 \uD1A0\uC131 \uD589\uC131",
