    "\u{1F31F}": "\uBC18\uC9DD\uC774\uB294 \uBCC4 \uB208\uBD80\uC2DC\uB294 \uBC18\uC9DD\uAC70\uB9AC\uB294 \uBC18\uC9DD\uBC18\uC9DD \uBC18\uC9DD\uC774\uB2E4 \uBC18\uC9DD\uC784 \uBC24 \uBCC4 \uBE5B\uB098\uB294 \uC2B9\uB9AC",
    "\u{1F320}": "\uBCC4\uB625\uBCC4 \uB099\uC131 \uB5A8\uC5B4\uC9C0\uB294 \uBC24 \uBCC4 \uC6B0\uC8FC \uC720\uC131",
    "\u{1F30C}": "\uC740\uD558\uC218 \uC6B0\uC8FC \uC740\uD558 \uD589\uC131",
    "\u2601\uFE0F": "\uAD6C\uB984 \uB0A0\uC528 \uD750\uB9BC",
    "\u26C5": "\uAD6C\uB984 \uB4A4\uC758 \uD574 \uAD6C\uB984 \uAD6C\uB984\uC5D0 \uAC00\uB9B0 \uD574 \uD574",
    "\u26C8\uFE0F": "\uBC88\uAC1C\uAC00 \uCE58\uB294 \uBE44\uAD6C\uB984 \uAD6C\uB984 \uB1CC\uC6B0 \uBC88\uAC1C \uBE44",
    "\u{1F324}\uFE0F": "\uC791\uC740 \uAD6C\uB984 \uB4A4\uC758 \uD0DC\uC591 \uAD6C\uB984 \uB0A0\uC528 \uD574 \uD750\uB9BC",
    "\u{1F325}\uFE0F": "\uD070 \uAD6C\uB984 \uB4A4\uC758 \uD0DC\uC591 \uAD6C\uB984 \uB0A0\uC528 \uD574 \uD750\uB9BC",
    "\u{1F326}\uFE0F": "\uBE44\uAD6C\uB984 \uB4A4\uC758 \uD0DC\uC591 \uAD6C\uB984 \uB0A0\uC528 \uBE44 \uD574",
    "\u{1F327}\uFE0F": "\uBE44\uAD6C\uB984 \uAD6C\uB984 \uB0A0\uC528 \uBE44",
    "\u{1F328}\uFE0F": "\uB208\uAD6C\uB984 \uAD6C\uB984 \uB0A0\uC528 \uB208 \uCD94\uC6C0",
    "\u{1F329}\uFE0F": "\uBC88\uAC1C\uAD6C\uB984 \uAD6C\uB984 \uB0A0\uC528 \uBC88\uAC1C",
